 async function createBoard(){if(!supabase)return;setError('');const{data,error:e}=await supabase.from('vision_boards').insert({year,title:`Meu visionboard de ${year}`}).select('id').single();if(e)setError(e.message);else{setBoardId(data.id);setNotice(`Seu visionboard de ${year} está pronto.`)}}
 async function saveGoal(event:FormEvent<HTMLFormElement>){
  event.preventDefault();if(!supabase||!boardId)return;setError('')
  const form=new FormData(event.currentTarget),title=String(form.get('title')??'').trim(),status=String(form.get('status')) as GoalStatus,amount=Number(form.get('progress')??0)
  let goalId=editingGoal?.id??null;const createdImageIds:string[]=[],createdPaths:string[]=[];let uploadedCoverUrl:string|null=null
  try{
   if(!title)throw new Error('Dê um nome para sua meta.')
   const patch=goalUpdate(status,amount,editingGoal?.status==='completed')
   const tags=form.getAll('tags').map(value=>String(value));const payload={title,description:String(form.get('description')??'').trim()||null,quarter:form.get('quarter')===''?null:Number(form.get('quarter')),due_date:String(form.get('due_date')??'')||null,tags,...patch}
   if(editingGoal){const{error:e}=await supabase.from('goals').update(payload).eq('id',goalId);if(e)throw e;if(files.length){const{error:coverError}=await supabase.from('goal_images').update({is_cover:false}).eq('goal_id',goalId);if(coverError)throw coverError}}
   else{const{data,error:e}=await supabase.from('goals').insert({...payload,vision_board_id:boardId,sort_order:goals.length}).select('id').single();if(e)throw e;goalId=data.id}
   for(let i=0;i<files.length;i++){
    const file=files[i];validateImage(file);const name=file.name.normalize('NFKD').replace(/[^a-zA-Z0-9._-]/g,'-').slice(-90),path=`${session!.user.id}/goals/${goalId}/${crypto.randomUUID()}-${name}`
    const{error:ue}=await supabase.storage.from('visionboard-private').upload(path,file,{contentType:file.type,upsert:false});if(ue)throw ue;createdPaths.push(path)
    const{data:image,error:ie}=await supabase.from('goal_images').insert({goal_id:goalId,storage_path:path,is_cover:i===selectedCover,sort_order:i}).select('id').single();if(ie)throw ie;createdImageIds.push(image.id);if(i===selectedCover){const{data:signed,error:se}=await supabase.storage.from('visionboard-private').createSignedUrl(path,3600);if(se)throw se;uploadedCoverUrl=signed.signedUrl}
   }
   const saved=editingGoal?{...editingGoal,...payload,coverUrl:uploadedCoverUrl??editingGoal.coverUrl} as Goal:{id:goalId!,...payload,created_at:new Date().toISOString(),coverUrl:uploadedCoverUrl} as Goal
   setGoals(prev=>editingGoal?prev.map(g=>g.id===goalId?saved:g):[...prev,saved]);setFiles([]);setExistingImages([]);setEditingGoal(null);setModal(null);setNotice('Meta salva com sucesso.')
  }catch(e){
   if(createdImageIds.length)await supabase.from('goal_images').delete().in('id',createdImageIds)
   if(createdPaths.length)await supabase.storage.from('visionboard-private').remove(createdPaths)
   if(!editingGoal&&goalId){const{data:persisted}=await supabase.from('goals').select('id,title,description,quarter,due_date,status,progress,created_at,tags').eq('id',goalId).maybeSingle();if(persisted){const savedDespiteImageError={...persisted,coverUrl:null} as Goal;setGoals(prev=>prev.some(g=>g.id===goalId)?prev:[...prev,savedDespiteImageError]);setEditingGoal(savedDespiteImageError);setNotice('Sua meta foi salva. Não conseguimos guardar uma das imagens; você pode tentar novamente.')}}
   setError(e instanceof Error?e.message:'Não foi possível salvar a meta.')
  }
 }
